for slug,ic,title,desc,tags,txt,items in services:
 c=content[slug]
 article='<article class="article"><p class="eyebrow">'+tags+'</p><h2>'+title+' — porozmawiajmy o Twoich potrzebach</h2><p>'+c['intro']+'</p>'
 article+='<ul class="checklist">'+''.join('<li>'+icon('check')+x+'</li>' for x in items)+'</ul>'
