js+="(function(){const root=document.querySelector('[data-hero-slider]');if(!root)return;const slides=[...root.querySelectorAll('.hero-slide')],controls=root.querySelector('.hero-slider-controls'),countEl=root.querySelector('.hero-slider-count'),prev=root.querySelector('.hero-slider-prev'),next=root.querySelector('.hero-slider-next');if(!slides.length)return;let index=slides.findIndex(s=>s.classList.contains('is-active'));if(index<0)index=0;const controlsHome=controls?{parent:controls.parentElement,next:controls.nextSibling}:null;const mobileSlider=()=>window.innerWidth<=768;const mountControls=()=>{if(!controls||!controlsHome)return;if(mobileSlider()){slides[index]?.querySelector('.hero-slide-visual')?.appendChild(controls);}else{controlsHome.parent.insertBefore(controls,controlsHome.next);}};const label=n=>String(n).padStart(2,'0');const sync=()=>{countEl.textContent=label(index+1)+' / '+label(slides.length);};const show=nextIndex=>{if(nextIndex===index||!slides[nextIndex])return;slides[index].classList.remove('is-active');slides[index].setAttribute('aria-hidden','true');index=nextIndex;slides[index].classList.add('is-active');slides[index].removeAttribute('aria-hidden');sync();mountControls();};const step=delta=>show((index+delta+slides.length)%slides.length);const skipMouseFocus=btn=>btn?.addEventListener('mousedown',e=>e.preventDefault());skipMouseFocus(prev);skipMouseFocus(next);const clickStep=(delta,e)=>{step(delta);if(document.activeElement===root)root.blur();else if(e?.currentTarget?.blur&&document.activeElement===e.currentTarget)e.currentTarget.blur()};prev?.addEventListener('click',e=>clickStep(-1,e));next?.addEventListener('click',e=>clickStep(1,e));root.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();step(-1);}else if(e.key==='ArrowRight'){e.preventDefault();step(1);}});let touchX=null;root.addEventListener('touchstart',e=>{touchX=e.changedTouches[0].clientX;},{passive:true});root.addEventListener('touchend',e=>{if(touchX==null)return;const dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>48)step(dx<0?1:-1);touchX=null;},{passive:true});matchMedia('(max-width:768px)').addEventListener('change',mountControls);mountControls();sync();})();"
